import blurJson from "../src/generated/real-image-blur.json";

/**
 * Canonical typed index of optimised category photos.
 *
 * Source photos: `/real-images/` (untouched, git-ignored).
 * Optimised files: `/public/images/products/{category}/{category}-{short-description}-{n}.webp`
 * (WebP, quality 82, fit inside 1200x1500, <150KB, aspect preserved, EXIF stripped —
 * generated by `scripts/real-images-optimise.ts` + category copies).
 *
 * Per-product wiring (slug -> main + gallery + alt + blur) lives in
 * `src/lib/data/image-map.ts`, which resolves every catalogue slug to one of
 * the files indexed here.
 */

export type PhotoCategory = "helmets" | "jackets" | "gloves" | "boots";

export type CategoryPhoto = {
  /** Public URL of the optimised WebP. */
  path: string;
  category: PhotoCategory;
  /** Source file under `/real-images/` (audit trail). */
  source: string;
  alt: string;
  blurDataURL: string;
};

const BLUR = blurJson as Record<string, string>;

/** Blur of the identical-bytes per-slug main file for a given slug. */
function blurOfProductMain(slug: string): string {
  return BLUR[`/images/products/${slug}/main.webp`] ?? "";
}

function photo(
  category: PhotoCategory,
  file: string,
  source: string,
  alt: string,
  blurSourceSlug: string,
): CategoryPhoto {
  return {
    path: `/images/products/${category}/${file}`,
    category,
    source: `real-images/${source}`,
    alt,
    blurDataURL: blurOfProductMain(blurSourceSlug),
  };
}

